//! Complete, data-driven typed ODF `style:graphic-properties` support.

use crate::{FlatOpenDocument, OpenDocumentPackage};
use litchi_core::{Error, Result, xml::escape_xml};
use quick_xml::{XmlVersion, events::{BytesStart, Event}, name::{QName, ResolveResult}, reader::NsReader};
use std::collections::{BTreeMap, HashSet};

const OFFICE:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:office:1.0";
const STYLE:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:style:1.0";
const DR3D:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:dr3d:1.0";
const DRAW:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:drawing:1.0";
const FO:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0";
const SVG:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0";
const TEXT:&[u8]=b"urn:oasis:names:tc:opendocument:xmlns:text:1.0";
const XLINK:&[u8]=b"http://www.w3.org/1999/xlink";
const OFFICE_NS:&str="urn:oasis:names:tc:opendocument:xmlns:office:1.0";
const STYLE_NS:&str="urn:oasis:names:tc:opendocument:xmlns:style:1.0";
const DR3D_NS:&str="urn:oasis:names:tc:opendocument:xmlns:dr3d:1.0";
const DRAW_NS:&str="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0";
const FO_NS:&str="urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0";
const SVG_NS:&str="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0";
const TEXT_NS:&str="urn:oasis:names:tc:opendocument:xmlns:text:1.0";
const XLINK_NS:&str="http://www.w3.org/1999/xlink";
const MAX_XML:usize=32*1024*1024;const MAX_VALUE:usize=1024*1024;const MAX_ATTRIBUTES:usize=256;const MAX_DEPTH:usize=128;const MAX_STYLES:usize=65_536;const MAX_TOTAL:usize=24*1024*1024;const MAX_EVENTS:usize=1_000_000;

fn bad(message:impl Into<String>)->Error{Error::InvalidFormat(message.into())}
fn safe(value:&str,name:&str,empty:bool)->Result<()>{if(!empty&&value.is_empty())||value.len()>MAX_VALUE||value.chars().any(|c|matches!(c,'\0'..='\u{8}'|'\u{b}'|'\u{c}'|'\u{e}'..='\u{1f}'|'\u{fffe}'|'\u{ffff}')){return Err(bad(format!("invalid {name}")))}Ok(())}
fn decimal(value:&str,signed:bool)->bool{let value=if signed{value.strip_prefix('-').unwrap_or(value)}else{value};if value.is_empty(){return false}let mut parts=value.split('.');let left=parts.next().unwrap_or_default();let right=parts.next();if parts.next().is_some(){return false}match right{None=>!left.is_empty()&&left.bytes().all(|b|b.is_ascii_digit()),Some(right)=>(!left.is_empty()||!right.is_empty())&&left.bytes().all(|b|b.is_ascii_digit())&&right.bytes().all(|b|b.is_ascii_digit())}}
fn length(value:&str,signed:bool,positive:bool,pixel_only:bool)->bool{let units=if pixel_only{&["px"][..]}else{&["cm","mm","in","pt","pc","px"][..]};units.iter().any(|unit|value.strip_suffix(unit).is_some_and(|number|decimal(number,signed)&&(!positive||number.bytes().any(|b|b.is_ascii_digit()&&b!=b'0'))))}
fn percent(value:&str,signed:bool,ranged:bool)->bool{let Some(number)=value.strip_suffix('%')else{return false};if!decimal(number,signed){return false}if!ranged{return true}number.trim_start_matches('-').parse::<f64>().is_ok_and(|number|number<=100.0)}
fn integer(value:&str,positive:bool)->bool{let value=value.strip_prefix('+').unwrap_or(value);if positive{!value.is_empty()&&value.bytes().all(|b|b.is_ascii_digit())&&value.bytes().any(|b|b!=b'0')}else{!value.is_empty()&&value.bytes().all(|b|b.is_ascii_digit())}}
fn duration(value:&str)->bool{let value=value.strip_prefix('-').unwrap_or(value);value.starts_with('P')&&value.len()>1&&value.bytes().any(|b|b.is_ascii_digit())&&value.bytes().all(|b|b.is_ascii_digit()||matches!(b,b'P'|b'T'|b'Y'|b'M'|b'D'|b'H'|b'S'|b'.'))}
fn ncname(value:&str,empty:bool)->bool{if value.is_empty(){return empty}let mut chars=value.chars();let Some(first)=chars.next()else{return false};(first=='_'||first.is_alphabetic())&&chars.all(|c|c=='_'||c=='-'||c=='.'||c.is_alphanumeric())}
fn clip(value:&str)->bool{let Some(inner)=value.strip_prefix("rect(").and_then(|v|v.strip_suffix(')'))else{return false};let values:Vec<_>=inner.split(',').map(str::trim).collect();values.len()==4&&values.iter().all(|value|*value=="auto"||["cm","mm","in","pt","pc"].iter().any(|unit|value.strip_suffix(unit).is_some_and(|number|decimal(number,true))))}

/// Closed namespaces used by the 174 graphic property names.
#[derive(Debug,Clone,Copy,PartialEq,Eq,PartialOrd,Ord,Hash)]pub enum GraphicPropertyNamespace{Dr3d,Draw,Fo,Style,Svg,Text}

/// A lexically validated value whose variant identifies its normative datatype.
#[derive(Debug,Clone,PartialEq,Eq)]pub enum GraphicPropertyValue{Boolean(bool),Color(String),Length(String),NonNegativeLength(String),PositiveLength(String),NonNegativePixelLength(String),Percent(String),ZeroToHundredPercent(String),SignedZeroToHundredPercent(String),NonNegativeInteger(String),PositiveInteger(String),Duration(String),Clip(String),StyleNameRef(String),StyleNameRefs(Vec<String>),Keyword(String),Text(String),Compound(String)}
impl GraphicPropertyValue{pub fn lexical(&self)->String{match self{Self::Boolean(value)=>value.to_string(),Self::Color(value)|Self::Length(value)|Self::NonNegativeLength(value)|Self::PositiveLength(value)|Self::NonNegativePixelLength(value)|Self::Percent(value)|Self::ZeroToHundredPercent(value)|Self::SignedZeroToHundredPercent(value)|Self::NonNegativeInteger(value)|Self::PositiveInteger(value)|Self::Duration(value)|Self::Clip(value)|Self::StyleNameRef(value)|Self::Keyword(value)|Self::Text(value)|Self::Compound(value)=>value.clone(),Self::StyleNameRefs(values)=>values.join(" ")}}}

include!("graphic_property_specs.rs");

fn validate_ref(reference:&str,value:&str)->Option<GraphicPropertyValue>{match reference{
 "boolean"=>match value{"true"=>Some(GraphicPropertyValue::Boolean(true)),"false"=>Some(GraphicPropertyValue::Boolean(false)),_=>None},
 "color"=>(value.len()==7&&value.starts_with('#')&&value[1..].bytes().all(|b|b.is_ascii_hexdigit())).then(||GraphicPropertyValue::Color(value.to_owned())),
 "length"|"coordinate"|"distance"=>length(value,true,false,false).then(||GraphicPropertyValue::Length(value.to_owned())),
 "nonNegativeLength"=>length(value,false,false,false).then(||GraphicPropertyValue::NonNegativeLength(value.to_owned())),
 "positiveLength"=>length(value,false,true,false).then(||GraphicPropertyValue::PositiveLength(value.to_owned())),
 "nonNegativePixelLength"=>length(value,false,false,true).then(||GraphicPropertyValue::NonNegativePixelLength(value.to_owned())),
 "percent"=>percent(value,true,false).then(||GraphicPropertyValue::Percent(value.to_owned())),
 "zeroToHundredPercent"=>percent(value,false,true).then(||GraphicPropertyValue::ZeroToHundredPercent(value.to_owned())),
 "signedZeroToHundredPercent"=>percent(value,true,true).then(||GraphicPropertyValue::SignedZeroToHundredPercent(value.to_owned())),
 "nonNegativeInteger"=>integer(value,false).then(||GraphicPropertyValue::NonNegativeInteger(value.to_owned())),
 "positiveInteger"=>integer(value,true).then(||GraphicPropertyValue::PositiveInteger(value.to_owned())),
 "duration"=>duration(value).then(||GraphicPropertyValue::Duration(value.to_owned())),
 "clipShape"=>clip(value).then(||GraphicPropertyValue::Clip(value.to_owned())),
 "styleNameRef"=>ncname(value,true).then(||GraphicPropertyValue::StyleNameRef(value.to_owned())),
 "styleNameRefs"=>{let values:Vec<_>=value.split_ascii_whitespace().map(str::to_owned).collect();values.iter().all(|value|ncname(value,false)).then(||GraphicPropertyValue::StyleNameRefs(values))},
 "horizontal-mirror"=>matches!(value,"horizontal"|"horizontal-on-odd"|"horizontal-on-even").then(||GraphicPropertyValue::Keyword(value.to_owned())),
 "borderWidths"=>{let values:Vec<_>=value.split_ascii_whitespace().collect();(values.len()==3&&values.iter().all(|value|length(value,false,true,false))).then(||GraphicPropertyValue::Compound(value.to_owned()))},
 "angle"|"string"|"shadowType"=>Some(GraphicPropertyValue::Text(value.to_owned())),_=>None}}
fn validate_spec(value:&str,keywords:&[&str],references:&[&str],list:bool,kind:GraphicPropertyKind)->Result<GraphicPropertyValue>{safe(value,"graphic property value",true)?;if kind==GraphicPropertyKind::DrawTileRepeatOffset{let parts:Vec<_>=value.split_ascii_whitespace().collect();if parts.len()==2&&percent(parts[0],false,true)&&matches!(parts[1],"horizontal"|"vertical"){return Ok(GraphicPropertyValue::Compound(value.to_owned()))}return Err(bad("invalid draw:tile-repeat-offset"))}if list{let parts:Vec<_>=value.split_ascii_whitespace().collect();if parts.iter().all(|part|keywords.contains(part)||references.iter().any(|reference|validate_ref(reference,part).is_some())){return Ok(GraphicPropertyValue::Compound(value.to_owned()))}return Err(bad(format!("invalid {}:{} list",kind.namespace().prefix(),kind.local_name())))}if keywords.contains(&value){return Ok(GraphicPropertyValue::Keyword(value.to_owned()))}for reference in references{if let Some(value)=validate_ref(reference,value){return Ok(value)}}Err(bad(format!("invalid {}:{} value",kind.namespace().prefix(),kind.local_name())))}

impl GraphicPropertyNamespace{fn prefix(self)->&'static str{match self{Self::Dr3d=>"dr3d",Self::Draw=>"draw",Self::Fo=>"fo",Self::Style=>"style",Self::Svg=>"svg",Self::Text=>"text"}}}

/// One closed-name typed graphic property.
#[derive(Debug,Clone,PartialEq,Eq)]pub struct GraphicProperty{kind:GraphicPropertyKind,value:GraphicPropertyValue}
impl GraphicProperty{pub fn new(kind:GraphicPropertyKind,lexical:&str)->Result<Self>{Ok(Self{kind,value:kind.parse_value(lexical)?})}pub fn kind(&self)->GraphicPropertyKind{self.kind}pub fn value(&self)->&GraphicPropertyValue{&self.value}pub fn lexical(&self)->String{self.value.lexical()}}

#[derive(Debug,Clone,Copy,PartialEq,Eq,PartialOrd,Ord,Hash)]pub enum GraphicPropertyChildKind{ListStyle,BackgroundImage,Columns}
impl GraphicPropertyChildKind{fn namespace(self)->GraphicPropertyNamespace{match self{Self::ListStyle=>GraphicPropertyNamespace::Text,Self::BackgroundImage|Self::Columns=>GraphicPropertyNamespace::Style}}fn local(self)->&'static str{match self{Self::ListStyle=>"list-style",Self::BackgroundImage=>"background-image",Self::Columns=>"columns"}}}
/// Bounded inert XML for an immediate normative child. It is never executed, rendered, or fetched.
#[derive(Debug,Clone,PartialEq,Eq)]pub struct GraphicPropertyChild{kind:GraphicPropertyChildKind,xml:String}
impl GraphicPropertyChild{pub fn new(kind:GraphicPropertyChildKind,xml:impl Into<String>)->Result<Self>{let xml=xml.into();validate_child(kind,&xml)?;Ok(Self{kind,xml})}pub fn kind(&self)->GraphicPropertyChildKind{self.kind}pub fn xml(&self)->&str{&self.xml}}
fn validate_child(kind:GraphicPropertyChildKind,xml:&str)->Result<()>{if xml.len()>MAX_VALUE{return Err(bad("graphic property child is too large"))}let wrapped=format!(r#"<wrapper xmlns:office="{OFFICE_NS}" xmlns:style="{STYLE_NS}" xmlns:dr3d="{DR3D_NS}" xmlns:draw="{DRAW_NS}" xmlns:fo="{FO_NS}" xmlns:svg="{SVG_NS}" xmlns:text="{TEXT_NS}" xmlns:xlink="{XLINK_NS}">{xml}</wrapper>"#);let mut reader=NsReader::from_reader(wrapped.as_bytes());let mut depth=0;let mut found=false;let mut events=0;loop{events+=1;if events>MAX_EVENTS{return Err(bad("graphic property child has too many events"))}match reader.read_event(){Ok(Event::Start(start))=>{if depth>=MAX_DEPTH{return Err(bad("graphic property child is too deep"))}let current=element(&reader,start.name());if depth==1{if found||current.0!=kind.namespace()||current.1!=kind.local().as_bytes(){return Err(bad("graphic property child has the wrong expanded name"))}found=true}depth+=1},Ok(Event::Empty(start))=>{let current=element(&reader,start.name());if depth==1{if found||current.0!=kind.namespace()||current.1!=kind.local().as_bytes(){return Err(bad("graphic property child has the wrong expanded name"))}found=true}},Ok(Event::Text(text))=>{let bytes:&[u8]=text.as_ref();if depth==1&&!bytes.iter().all(u8::is_ascii_whitespace){return Err(bad("graphic property child has sibling text"))}},Ok(Event::CData(text))=>{let bytes:&[u8]=text.as_ref();if depth==1&&!bytes.iter().all(u8::is_ascii_whitespace){return Err(bad("graphic property child has sibling text"))}},Ok(Event::End(_))=>depth=depth.checked_sub(1).ok_or_else(||bad("invalid graphic property child"))?,Ok(Event::Decl(_))|Ok(Event::DocType(_))|Ok(Event::PI(_))=>return Err(bad("declarations, DTDs, and processing instructions are not allowed in graphic children")),Ok(Event::Eof)=>break,Ok(_)=>{},Err(error)=>return Err(bad(format!("invalid graphic property child: {error}")))}}if!found||depth!=0{return Err(bad("truncated graphic property child"))}Ok(())}

/// Complete typed `style:graphic-properties` value.
#[derive(Debug,Clone,Default,PartialEq,Eq)]pub struct GraphicStyleProperties{properties:BTreeMap<GraphicPropertyKind,GraphicPropertyValue>,children:BTreeMap<GraphicPropertyChildKind,GraphicPropertyChild>}
impl GraphicStyleProperties{
 pub fn set(&mut self,property:GraphicProperty)->Option<GraphicPropertyValue>{self.properties.insert(property.kind,property.value)}pub fn set_lexical(&mut self,kind:GraphicPropertyKind,value:&str)->Result<Option<GraphicPropertyValue>>{Ok(self.set(GraphicProperty::new(kind,value)?))}pub fn get(&self,kind:GraphicPropertyKind)->Option<&GraphicPropertyValue>{self.properties.get(&kind)}pub fn remove(&mut self,kind:GraphicPropertyKind)->Option<GraphicPropertyValue>{self.properties.remove(&kind)}pub fn iter(&self)->impl Iterator<Item=(GraphicPropertyKind,&GraphicPropertyValue)>{self.properties.iter().map(|(kind,value)|(*kind,value))}
 pub fn set_child(&mut self,child:GraphicPropertyChild)->Option<GraphicPropertyChild>{self.children.insert(child.kind,child)}pub fn child(&self,kind:GraphicPropertyChildKind)->Option<&GraphicPropertyChild>{self.children.get(&kind)}pub fn remove_child(&mut self,kind:GraphicPropertyChildKind)->Option<GraphicPropertyChild>{self.children.remove(&kind)}
 pub fn from_xml_fragment(fragment:&str)->Result<Self>{let xml=format!(r#"<office:document xmlns:office="{OFFICE_NS}" xmlns:style="{STYLE_NS}"><office:styles><style:style style:name="fragment" style:family="graphic">{fragment}</style:style></office:styles></office:document>"#);let mut set=parse_graphic_style_properties(&xml)?;set.styles.pop().and_then(|style|style.properties).ok_or_else(||bad("fragment does not contain style:graphic-properties"))}
 pub fn to_xml_fragment(&self)->Result<String>{let mut xml=format!(r#"<style:graphic-properties xmlns:office="{OFFICE_NS}" xmlns:style="{STYLE_NS}" xmlns:dr3d="{DR3D_NS}" xmlns:draw="{DRAW_NS}" xmlns:fo="{FO_NS}" xmlns:svg="{SVG_NS}" xmlns:text="{TEXT_NS}" xmlns:xlink="{XLINK_NS}""#);for(kind,value)in&self.properties{xml.push(' ');xml.push_str(kind.namespace().prefix());xml.push(':');xml.push_str(kind.local_name());xml.push_str("=\"");xml.push_str(&escape_xml(&value.lexical()));xml.push('"')}if self.children.is_empty(){xml.push_str("/>")}else{xml.push('>');for child in self.children.values(){validate_child(child.kind,&child.xml)?;xml.push_str(&child.xml)}xml.push_str("</style:graphic-properties>")}Ok(xml)}
}

#[derive(Debug,Clone,PartialEq,Eq)]pub struct GraphicStyleRecord{pub name:Option<String>,pub parent_style_name:Option<String>,pub is_default_style:bool,pub properties:Option<GraphicStyleProperties>}
impl GraphicStyleRecord{pub fn named(name:impl Into<String>,properties:Option<GraphicStyleProperties>)->Result<Self>{let value=Self{name:Some(name.into()),parent_style_name:None,is_default_style:false,properties};value.validate()?;Ok(value)}pub fn default_style(properties:Option<GraphicStyleProperties>)->Self{Self{name:None,parent_style_name:None,is_default_style:true,properties}}pub fn validate(&self)->Result<()>{match(&self.name,self.is_default_style){(Some(value),false)if ncname(value,false)=>{},(None,true)=>{},_=>return Err(bad("invalid graphic style identity"))}if let Some(value)=&self.parent_style_name{if self.is_default_style||!ncname(value,false){return Err(bad("invalid parent graphic style name"))}}Ok(())}pub fn to_xml_fragment(&self)->Result<String>{self.validate()?;let tag=if self.is_default_style{"default-style"}else{"style"};let mut xml=format!(r#"<style:{tag} xmlns:style="{STYLE_NS}" style:family="graphic""#);if let Some(value)=&self.name{xml.push_str(&format!(r#" style:name="{}""#,escape_xml(value)))}if let Some(value)=&self.parent_style_name{xml.push_str(&format!(r#" style:parent-style-name="{}""#,escape_xml(value)))}if let Some(value)=&self.properties{xml.push('>');xml.push_str(&value.to_xml_fragment()?);xml.push_str(&format!("</style:{tag}>"))}else{xml.push_str("/>")}Ok(xml)}}
#[derive(Debug,Clone,Default,PartialEq,Eq)]pub struct GraphicStylePropertiesSet{pub styles:Vec<GraphicStyleRecord>}impl GraphicStylePropertiesSet{pub fn get(&self,name:&str)->Option<&GraphicStyleRecord>{self.styles.iter().find(|style|style.name.as_deref()==Some(name))}pub fn default_style(&self)->Option<&GraphicStyleRecord>{self.styles.iter().find(|style|style.is_default_style)}}

fn property_ns(value:ResolveResult<'_>)->Option<GraphicPropertyNamespace>{match value{ResolveResult::Bound(value)if value.as_ref()==DR3D=>Some(GraphicPropertyNamespace::Dr3d),ResolveResult::Bound(value)if value.as_ref()==DRAW=>Some(GraphicPropertyNamespace::Draw),ResolveResult::Bound(value)if value.as_ref()==FO=>Some(GraphicPropertyNamespace::Fo),ResolveResult::Bound(value)if value.as_ref()==STYLE=>Some(GraphicPropertyNamespace::Style),ResolveResult::Bound(value)if value.as_ref()==SVG=>Some(GraphicPropertyNamespace::Svg),ResolveResult::Bound(value)if value.as_ref()==TEXT=>Some(GraphicPropertyNamespace::Text),_=>None}}
#[derive(Clone,Copy,PartialEq,Eq)]enum ElementNs{Office,Style,Dr3d,Draw,Fo,Svg,Text,Xlink,Other}
impl PartialEq<GraphicPropertyNamespace> for ElementNs{fn eq(&self,other:&GraphicPropertyNamespace)->bool{matches!((self,other),(Self::Dr3d,GraphicPropertyNamespace::Dr3d)|(Self::Draw,GraphicPropertyNamespace::Draw)|(Self::Fo,GraphicPropertyNamespace::Fo)|(Self::Style,GraphicPropertyNamespace::Style)|(Self::Svg,GraphicPropertyNamespace::Svg)|(Self::Text,GraphicPropertyNamespace::Text))}}
fn ens(value:ResolveResult<'_>)->ElementNs{match value{ResolveResult::Bound(value)if value.as_ref()==OFFICE=>ElementNs::Office,ResolveResult::Bound(value)if value.as_ref()==STYLE=>ElementNs::Style,ResolveResult::Bound(value)if value.as_ref()==DR3D=>ElementNs::Dr3d,ResolveResult::Bound(value)if value.as_ref()==DRAW=>ElementNs::Draw,ResolveResult::Bound(value)if value.as_ref()==FO=>ElementNs::Fo,ResolveResult::Bound(value)if value.as_ref()==SVG=>ElementNs::Svg,ResolveResult::Bound(value)if value.as_ref()==TEXT=>ElementNs::Text,ResolveResult::Bound(value)if value.as_ref()==XLINK=>ElementNs::Xlink,_=>ElementNs::Other}}
fn element(reader:&NsReader<&[u8]>,name:QName<'_>)->(ElementNs,Vec<u8>){let(namespace,local)=reader.resolver().resolve_element(name);(ens(namespace),local.as_ref().to_vec())}
fn raw_attrs(reader:&NsReader<&[u8]>,version:XmlVersion,start:&BytesStart<'_>)->Result<Vec<(Option<GraphicPropertyNamespace>,Vec<u8>,String)>>{let mut out=Vec::new();for attribute in start.attributes().with_checks(true){let attribute=attribute.map_err(|error|bad(format!("invalid graphic property attribute: {error}")))?;if attribute.key.as_ref()==b"xmlns"||attribute.key.as_ref().starts_with(b"xmlns:"){continue}if out.len()>=MAX_ATTRIBUTES{return Err(bad("too many graphic property attributes"))}let(namespace,local)=reader.resolver().resolve_attribute(attribute.key);let namespace=property_ns(namespace);let value=attribute.decoded_and_normalized_value(version,reader.decoder()).map_err(|error|bad(format!("invalid graphic property value: {error}")))?.into_owned();safe(&value,"graphic property value",true)?;out.push((namespace,local.as_ref().to_vec(),value))}Ok(out)}
fn style_header(reader:&NsReader<&[u8]>,version:XmlVersion,start:&BytesStart<'_>,default:bool)->Result<Option<GraphicStyleRecord>>{let mut family=None;let mut name=None;let mut parent=None;for attribute in start.attributes().with_checks(true){let attribute=attribute.map_err(|error|bad(format!("invalid graphic style attribute: {error}")))?;let(namespace,local)=reader.resolver().resolve_attribute(attribute.key);if ens(namespace)!=ElementNs::Style{continue}let value=attribute.decoded_and_normalized_value(version,reader.decoder()).map_err(|error|bad(format!("invalid graphic style value: {error}")))?.into_owned();match local.as_ref(){b"family"=>family=Some(value),b"name"=>name=Some(value),b"parent-style-name"=>parent=Some(value),_=>{}}}if family.as_deref()!=Some("graphic"){return Ok(None)}let value=GraphicStyleRecord{name,parent_style_name:parent,is_default_style:default,properties:None};value.validate()?;Ok(Some(value))}
fn parse_properties(reader:&NsReader<&[u8]>,version:XmlVersion,start:&BytesStart<'_>)->Result<GraphicStyleProperties>{let attrs=raw_attrs(reader,version,start)?;let mut properties=GraphicStyleProperties::default();let mut seen=HashSet::new();for(namespace,local,value)in attrs{let namespace=namespace.ok_or_else(||bad("unknown style:graphic-properties attribute namespace"))?;let kind=GraphicPropertyKind::from_expanded(namespace,&local).ok_or_else(||bad("unknown style:graphic-properties attribute or wrong namespace"))?;if!seen.insert(kind){return Err(bad("duplicate style:graphic-properties attribute"))}properties.set_lexical(kind,&value)?;}Ok(properties)}
fn child_kind(current:&(ElementNs,Vec<u8>))->Option<GraphicPropertyChildKind>{match(current.0,current.1.as_slice()){(ElementNs::Text,b"list-style")=>Some(GraphicPropertyChildKind::ListStyle),(ElementNs::Style,b"background-image")=>Some(GraphicPropertyChildKind::BackgroundImage),(ElementNs::Style,b"columns")=>Some(GraphicPropertyChildKind::Columns),_=>None}}
fn boundary(xml:&str,end:usize)->Result<usize>{xml[..end].rfind('<').ok_or_else(||bad("invalid XML event boundary"))}
struct Active{depth:usize,style:GraphicStyleRecord,seen:bool,property_depth:Option<usize>,child:Option<(GraphicPropertyChildKind,usize,usize)>}
fn push(out:&mut Vec<GraphicStyleRecord>,style:GraphicStyleRecord,total:&mut usize)->Result<()>{if out.len()>=MAX_STYLES||out.iter().any(|value|value.name==style.name&&value.is_default_style==style.is_default_style){return Err(bad("duplicate or excessive graphic style"))}*total+=style.to_xml_fragment()?.len();if*total>MAX_TOTAL{return Err(bad("graphic style data is too large"))}out.push(style);Ok(())}
/// Parse direct graphic-family styles from standard style containers.
pub fn parse_graphic_style_properties(xml:&str)->Result<GraphicStylePropertiesSet>{if xml.len()>MAX_XML{return Err(bad("styles XML is too large"))}let mut reader=NsReader::from_reader(xml.as_bytes());reader.config_mut().trim_text(false);let mut version=XmlVersion::Implicit1_0;let mut stack:Vec<(ElementNs,Vec<u8>)>=Vec::new();let mut active:Option<Active>=None;let mut out=Vec::new();let mut total=0;let mut events=0;loop{events+=1;if events>MAX_EVENTS{return Err(bad("styles XML has too many events"))}match reader.read_event(){Ok(Event::Start(start))=>{if stack.len()>=MAX_DEPTH{return Err(bad("styles XML is too deep"))}let end=reader.buffer_position()as usize;let begin=boundary(xml,end)?;let current=element(&reader,start.name());let parent=stack.last();let direct=parent.is_some_and(|value|value.0==ElementNs::Office&&matches!(value.1.as_slice(),b"styles"|b"automatic-styles"))&&current.0==ElementNs::Style&&matches!(current.1.as_slice(),b"style"|b"default-style");stack.push(current.clone());let depth=stack.len();if direct{if let Some(style)=style_header(&reader,version,&start,current.1==b"default-style")?{active=Some(Active{depth,style,seen:false,property_depth:None,child:None})}continue}if let Some(value)=active.as_mut(){if value.child.is_some(){continue}if depth==value.depth+1&&current.0==ElementNs::Style&&current.1==b"graphic-properties"{if value.seen{return Err(bad("duplicate style:graphic-properties"))}value.seen=true;value.style.properties=Some(parse_properties(&reader,version,&start)?);value.property_depth=Some(depth)}else if current.1==b"graphic-properties"{return Err(bad("style:graphic-properties has invalid namespace or parent"))}else if value.property_depth.is_some_and(|p|depth==p+1){let kind=child_kind(&current).ok_or_else(||bad("unexpected style:graphic-properties child"))?;if value.style.properties.as_ref().unwrap().child(kind).is_some(){return Err(bad("duplicate graphic property child"))}value.child=Some((kind,depth,begin))}else if value.property_depth.is_some_and(|p|depth>p){return Err(bad("unexpected style:graphic-properties child"))}}},Ok(Event::Empty(start))=>{let end=reader.buffer_position()as usize;let begin=boundary(xml,end)?;let current=element(&reader,start.name());let parent=stack.last();let depth=stack.len()+1;let direct=parent.is_some_and(|value|value.0==ElementNs::Office&&matches!(value.1.as_slice(),b"styles"|b"automatic-styles"))&&current.0==ElementNs::Style&&matches!(current.1.as_slice(),b"style"|b"default-style");if direct{if let Some(style)=style_header(&reader,version,&start,current.1==b"default-style")?{push(&mut out,style,&mut total)?}continue}if let Some(value)=active.as_mut(){if value.child.is_some(){continue}if depth==value.depth+1&&current.0==ElementNs::Style&&current.1==b"graphic-properties"{if value.seen{return Err(bad("duplicate style:graphic-properties"))}value.seen=true;value.style.properties=Some(parse_properties(&reader,version,&start)?)}else if current.1==b"graphic-properties"{return Err(bad("style:graphic-properties has invalid namespace or parent"))}else if value.property_depth.is_some_and(|p|depth==p+1){let kind=child_kind(&current).ok_or_else(||bad("unexpected style:graphic-properties child"))?;let child=GraphicPropertyChild::new(kind,&xml[begin..end])?;if value.style.properties.as_mut().unwrap().set_child(child).is_some(){return Err(bad("duplicate graphic property child"))}}else if value.property_depth.is_some_and(|p|depth>p){return Err(bad("unexpected style:graphic-properties child"))}}},Ok(Event::Text(text))=>{let bytes:&[u8]=text.as_ref();if active.as_ref().is_some_and(|value|value.property_depth.is_some()&&value.child.is_none())&&!bytes.iter().all(u8::is_ascii_whitespace){return Err(bad("unexpected text in style:graphic-properties"))}},Ok(Event::CData(text))=>{let bytes:&[u8]=text.as_ref();if active.as_ref().is_some_and(|value|value.property_depth.is_some()&&value.child.is_none())&&!bytes.iter().all(u8::is_ascii_whitespace){return Err(bad("unexpected text in style:graphic-properties"))}},Ok(Event::End(_))=>{let end=reader.buffer_position()as usize;let depth=stack.len();if let Some(value)=active.as_mut(){if value.child.as_ref().is_some_and(|(_,child_depth,_)|*child_depth==depth){let(kind,_,begin)=value.child.take().unwrap();let child=GraphicPropertyChild::new(kind,&xml[begin..end])?;value.style.properties.as_mut().unwrap().set_child(child);}if value.property_depth==Some(depth){value.property_depth=None}}if active.as_ref().is_some_and(|value|value.depth==depth){push(&mut out,active.take().unwrap().style,&mut total)?}stack.pop();},Ok(Event::Decl(decl))=>version=decl.xml_version().map_err(|error|bad(format!("unsupported XML version: {error}")))?,Ok(Event::DocType(_))|Ok(Event::PI(_))=>return Err(bad("DTD and processing instructions are not allowed")),Ok(Event::Eof)=>break,Ok(_)=>{},Err(error)=>return Err(bad(format!("invalid styles XML: {error}")))}}if!stack.is_empty()||active.is_some(){return Err(bad("truncated styles XML"))}Ok(GraphicStylePropertiesSet{styles:out})}

#[derive(Default)]struct Span{start:usize,end:usize,end_start:usize,qname:String,empty:bool}#[derive(Default)]struct Target{style:Span,properties:Option<Span>}
fn replace(xml:&str,span:&Span,value:&str)->String{format!("{}{}{}",&xml[..span.start],value,&xml[span.end..])}fn expand(xml:&str,span:&Span,value:&str)->Result<String>{let raw=&xml[span.start..span.end];let slash=raw.rfind("/>").ok_or_else(||bad("invalid empty style"))?;Ok(replace(xml,span,&format!("{}>{value}</{}>",&raw[..slash],span.qname)))}
/// Losslessly replace, insert, or remove one existing graphic style property element.
pub fn set_graphic_style_properties_xml(xml:&str,requested:&GraphicStyleRecord)->Result<String>{requested.validate()?;if xml.len()>MAX_XML{return Err(bad("styles XML is too large"))}let mut reader=NsReader::from_reader(xml.as_bytes());let mut version=XmlVersion::Implicit1_0;let mut stack:Vec<(ElementNs,Vec<u8>)>=Vec::new();let mut target_depth=None;let mut active:Option<Target>=None;let mut found=None;loop{match reader.read_event(){Ok(Event::Start(start))=>{let end=reader.buffer_position()as usize;let begin=boundary(xml,end)?;let current=element(&reader,start.name());let parent=stack.last();let direct=parent.is_some_and(|value|value.0==ElementNs::Office&&matches!(value.1.as_slice(),b"styles"|b"automatic-styles"))&&current.0==ElementNs::Style&&matches!(current.1.as_slice(),b"style"|b"default-style");stack.push(current.clone());let depth=stack.len();if direct{if let Some(style)=style_header(&reader,version,&start,current.1==b"default-style")?&&style.name==requested.name&&style.is_default_style==requested.is_default_style{if active.is_some()||found.is_some(){return Err(bad("duplicate target graphic style"))}target_depth=Some(depth);active=Some(Target{style:Span{start:begin,qname:String::from_utf8_lossy(start.name().as_ref()).into_owned(),..Default::default()},..Default::default()})}}else if target_depth.is_some_and(|d|depth==d+1)&&current.0==ElementNs::Style&&current.1==b"graphic-properties"{let span=Span{start:begin,qname:String::from_utf8_lossy(start.name().as_ref()).into_owned(),..Default::default()};if active.as_mut().unwrap().properties.replace(span).is_some(){return Err(bad("duplicate style:graphic-properties"))}}},Ok(Event::Empty(start))=>{let end=reader.buffer_position()as usize;let begin=boundary(xml,end)?;let current=element(&reader,start.name());let parent=stack.last();let depth=stack.len()+1;let direct=parent.is_some_and(|value|value.0==ElementNs::Office&&matches!(value.1.as_slice(),b"styles"|b"automatic-styles"))&&current.0==ElementNs::Style&&matches!(current.1.as_slice(),b"style"|b"default-style");let span=Span{start:begin,end,end_start:begin,qname:String::from_utf8_lossy(start.name().as_ref()).into_owned(),empty:true};if direct{if let Some(style)=style_header(&reader,version,&start,current.1==b"default-style")?&&style.name==requested.name&&style.is_default_style==requested.is_default_style{if active.is_some()||found.is_some(){return Err(bad("duplicate target graphic style"))}found=Some(Target{style:span,..Default::default()})}}else if target_depth.is_some_and(|d|depth==d+1)&&current.0==ElementNs::Style&&current.1==b"graphic-properties"{if active.as_mut().unwrap().properties.replace(span).is_some(){return Err(bad("duplicate style:graphic-properties"))}}},Ok(Event::End(_))=>{let end=reader.buffer_position()as usize;let begin=boundary(xml,end)?;let depth=stack.len();if let Some(spans)=active.as_mut(){if spans.properties.as_ref().is_some_and(|span|span.end==0)&&target_depth.is_some_and(|d|depth==d+1){let span=spans.properties.as_mut().unwrap();span.end_start=begin;span.end=end}if target_depth==Some(depth){spans.style.end_start=begin;spans.style.end=end;found=active.take();target_depth=None}}stack.pop();},Ok(Event::Decl(decl))=>version=decl.xml_version().map_err(|error|bad(format!("unsupported XML version: {error}")))?,Ok(Event::DocType(_))|Ok(Event::PI(_))=>return Err(bad("DTD and processing instructions are not allowed")),Ok(Event::Eof)=>break,Ok(_)=>{},Err(error)=>return Err(bad(format!("invalid styles XML: {error}")))}}let spans=found.ok_or_else(||bad("target graphic style does not exist"))?;let replacement=requested.properties.as_ref().map(GraphicStyleProperties::to_xml_fragment).transpose()?;if let Some(properties)=&spans.properties{return Ok(replace(xml,properties,replacement.as_deref().unwrap_or("")))}let Some(replacement)=replacement else{return Ok(xml.to_owned())};if spans.style.empty{return expand(xml,&spans.style,&replacement)}let mut out=xml.to_owned();out.insert_str(spans.style.end_start,&replacement);Ok(out)}

impl OpenDocumentPackage{pub fn graphic_style_properties(&self)->Result<GraphicStylePropertiesSet>{self.styles_xml()?.map_or_else(||Ok(Default::default()),|xml|parse_graphic_style_properties(&xml))}}
impl FlatOpenDocument{pub fn graphic_style_properties(&self)->Result<GraphicStylePropertiesSet>{parse_graphic_style_properties(self.xml())}}

#[cfg(test)]mod tests{use super::*;const HEAD:&str=r#"<office:document xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:style="urn:oasis:names:tc:opendocument:xmlns:style:1.0" xmlns:dr3d="urn:oasis:names:tc:opendocument:xmlns:dr3d:1.0" xmlns:draw="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0" xmlns:fo="urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0" xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" xmlns:xlink="http://www.w3.org/1999/xlink"><office:automatic-styles>"#;fn doc(body:&str)->String{format!("{HEAD}{body}</office:automatic-styles></office:document>")}
 #[test]fn every_normative_property_kind_round_trips(){let mut value=GraphicStyleProperties::default();for kind in GraphicPropertyKind::ALL{value.set_lexical(*kind,kind.example()).unwrap();}value.set_child(GraphicPropertyChild::new(GraphicPropertyChildKind::ListStyle,r#"<text:list-style style:name="L"/>"#).unwrap());value.set_child(GraphicPropertyChild::new(GraphicPropertyChildKind::BackgroundImage,r#"<style:background-image xlink:href="Pictures/a&amp;b.png"/>"#).unwrap());value.set_child(GraphicPropertyChild::new(GraphicPropertyChildKind::Columns,r#"<style:columns fo:column-count="2" fo:column-gap="0cm"/>"#).unwrap());let fragment=value.to_xml_fragment().unwrap();assert_eq!(GraphicStyleProperties::from_xml_fragment(&fragment).unwrap(),value);assert_eq!(value.iter().count(),174)}
 #[test]fn parses_real_odfdo_fixture_values(){let fixture=include_str!("../../../3rdparty/odfdo/tests/samples/images.fodt");let begin=fixture.find(r#"<style:style style:name="fr1" style:family="graphic""#).unwrap();let end=begin+fixture[begin..].find("</style:style>").unwrap()+"</style:style>".len();let set=parse_graphic_style_properties(&doc(&fixture[begin..end])).unwrap();let value=set.get("fr1").unwrap().properties.as_ref().unwrap();assert_eq!(value.get(GraphicPropertyKind::DrawGamma).unwrap().lexical(),"100%");assert_eq!(value.get(GraphicPropertyKind::FoClip).unwrap().lexical(),"rect(0cm, 0cm, 0cm, 0cm)")}
 #[test]fn lossless_replace_insert_remove(){let original=doc("<!--keep--><style:style style:name=\"a\" style:family=\"graphic\"><x:k xmlns:x=\"urn:k\"/></style:style><style:style style:name=\"b\" style:family=\"graphic\"><style:graphic-properties draw:fill=\"none\"/></style:style>");let mut properties=GraphicStyleProperties::default();properties.set_lexical(GraphicPropertyKind::DrawFill,"solid").unwrap();let mut a=GraphicStyleRecord::named("a",Some(properties)).unwrap();let inserted=set_graphic_style_properties_xml(&original,&a).unwrap();assert!(inserted.contains("<x:k xmlns:x=\"urn:k\"/><style:graphic-properties"));a.properties=None;let restored=set_graphic_style_properties_xml(&inserted,&a).unwrap();assert_eq!(restored,original);let removed=set_graphic_style_properties_xml(&restored,&GraphicStyleRecord::named("b",None).unwrap()).unwrap();assert!(!removed.contains("draw:fill=\"none\""));assert!(removed.contains("<!--keep-->"))}
 #[test]fn rejects_malformed_and_capped_input(){for body in[r#"<style:style style:name="a" style:family="graphic"><style:graphic-properties draw:fill="wrong"/></style:style>"#,r#"<style:style style:name="a" style:family="graphic"><style:graphic-properties draw:fill="none" draw:fill="solid"/></style:style>"#,r#"<style:style style:name="a" style:family="graphic"><draw:graphic-properties/></style:style>"#,r#"<style:style style:name="a" style:family="graphic"><style:graphic-properties><draw:columns/></style:graphic-properties></style:style>"#,r#"<style:style style:name="a" style:family="graphic"><style:graphic-properties draw:tile-repeat-offset="101% horizontal"/></style:style>"#]{assert!(parse_graphic_style_properties(&doc(body)).is_err(),"accepted {body}")}let huge="x".repeat(MAX_VALUE+1);assert!(GraphicProperty::new(GraphicPropertyKind::DrawStrokeDash,&huge).is_err());let mut attributes=String::new();for index in 0..=MAX_ATTRIBUTES{attributes.push_str(&format!(" x:a{index}=\"1\""))}let xml=doc(&format!(r#"<style:style style:name="a" style:family="graphic"><style:graphic-properties xmlns:x="urn:x"{attributes}/></style:style>"#));assert!(parse_graphic_style_properties(&xml).is_err())}
}
